/*=----------------------------------------------------------------------=*\
   Use :Performs a differential ADC sample and returns voltage in volts
       :
       :Parameters for macro SampleDiffVolts:
       :  ChannelA : Positive channel: 0-3 (AN0-AN3)
       :  ChannelB : Negative channel: 0-3 (AN0-AN3)
       :  Gain : PGA Gain: 0=1x, 1=2x, 2=4x, 3=8x, 4=16x, 5=32x, 6=64x, 7=128x
       :
       :Returns : Differential voltage in volts
\*=----------------------------------------------------------------------=*/
MX_FLOAT FCM_SampleDiffVolts(MX_UINT8 FCL_CHANNELA, MX_UINT8 FCL_CHANNELB, MX_UINT8 FCL_GAIN)
{
  //Local variable definitions
  MX_SINT32 FCL_RAWVALUE;
  MX_UINT8 FCL_GAINVALUE;
  MX_FLOAT FCR_RETVAL; // Differential voltage in volts


  // Read Raw Value
  FCL_RAWVALUE = FCM_SampleDiffRAW(FCL_CHANNELA, FCL_CHANNELB, FCL_GAIN);

  // Switch
  switch (FCL_GAIN)
  {
    case 0:
    {

      // Calculation
      FCL_GAINVALUE = 1;

      break;
    }
    case 1:
    {

      // Calculation
      FCL_GAINVALUE = 2;

      break;
    }
    case 2:
    {

      // Calculation
      FCL_GAINVALUE = 4;

      break;
    }
    case 3:
    {

      // Calculation
      FCL_GAINVALUE = 8;

      break;
    }
    case 4:
    {

      // Calculation
      FCL_GAINVALUE = 16;

      break;
    }
    case 5:
    {

      // Calculation
      FCL_GAINVALUE = 32;

      break;
    }
    case 6:
    {

      // Calculation
      FCL_GAINVALUE = 64;

      break;
    }
    case 7:
    {

      // Calculation
      FCL_GAINVALUE = 128;

      break;
    }
    default:
    {
      // Calculation
      FCL_GAINVALUE = 1;

    }
  }

  // Convert to voltage
  FCR_RETVAL = flt_div(flt_mul((flt_div(flt_fromi(FCL_RAWVALUE), 8388608.0)), 2.048), flt_fromi(FCL_GAINVALUE));

  return (FCR_RETVAL);

}

