/*=----------------------------------------------------------------------=*\
   Use :Reads the RTD sensor and returns resistance in ohms
       :
       :Returns : RTD resistance in ohms
\*=----------------------------------------------------------------------=*/
MX_FLOAT FCM_ReadRTDResistance()
{
  //Local variable definitions
  MX_SINT32 FCL_RAWVALUE; // 24-bit ADC raw value
  MX_FLOAT FCL_GAINVALUE; // PGA gain value (1.0, 2.0, 4.0, etc.)
  MX_UINT8 FCL_GAINREG; // Gain setting from ConfigReg0
  MX_FLOAT FCL_TEMP = (0.0);
  MX_FLOAT FCR_RETVAL; // RTD resistance in ohms


  // User Macro
  FCL_RAWVALUE = FCM_ReadSample();

  // Extract PGA gain from ConfigReg0 (bits 4-6)
  FCL_GAINREG = (FCV_CONFIGREG0 >> 1) & 0x07;

  // Convert gain register to gain value
  switch (FCL_GAINREG)
  {
    case 1:
    {

      // Gain 2x
      FCL_GAINVALUE = 2.0;

      break;
    }
    case 2:
    {

      // Gain 4x
      FCL_GAINVALUE = 4.0;

      break;
    }
    case 3:
    {

      // Gain 8x
      FCL_GAINVALUE = 8.0;

      break;
    }
    case 4:
    {

      // Gain 16x
      FCL_GAINVALUE = 16.0;

      break;
    }
    case 5:
    {

      // Gain 32x
      FCL_GAINVALUE = 32.0;

      break;
    }
    case 6:
    {

      // Gain 64x
      FCL_GAINVALUE = 64.0;

      break;
    }
    case 7:
    {

      // Gain 128x
      FCL_GAINVALUE = 128.0;

      break;
    }
    default:
    {
      // Gain 1x
      FCL_GAINVALUE = 1.0;

    }
  }

  // Calculation
  FCR_RETVAL = 0;

  // 2 Wire RTD
  if (1 == 0)
  {  

    // Calculate RTD resistance 2 Wire
    FCR_RETVAL = flt_div(flt_mul(4700, flt_fromi(FCL_RAWVALUE)), (flt_mul(8388608.0, FCL_GAINVALUE)));

  // } else {

  }

  // 3 Wire RTD - Low side ref
  if (1 == 1)
  {  

    // Calculate RTD resistance using 3W low-side reference
    FCR_RETVAL = flt_div(flt_mul(4700, flt_fromi(FCL_RAWVALUE)), (flt_mul(4194304.0, FCL_GAINVALUE)));

  // } else {

  }

  // 4 Wire RTD
  if (1 == 2)
  {  

    // Calculate RTD resistance 2 Wire
    FCR_RETVAL = flt_div(flt_mul(4700, flt_fromi(FCL_RAWVALUE)), (flt_mul(8388608.0, FCL_GAINVALUE)));

  // } else {

  }

  return (FCR_RETVAL);

}

